/* news quiz */
.newsq{display:grid;gap:10px}
.nq{border:1px solid var(--line2);padding:10px 12px;display:grid;gap:8px;background:rgba(4,8,18,.6)}
.nq b{font-weight:600;display:flex;gap:8px;align-items:center}
.nq .lamp{width:10px;height:10px;border-radius:50%;background:#2a1018;flex:none}
.nq.ok{border-color:var(--mint)}.nq.ok .lamp{background:var(--mint);box-shadow:0 0 10px var(--mint)}
/* pouch lock */
.plock{display:grid;justify-items:center;gap:8px;padding:12px;border:1px solid var(--amber);background:rgba(255,178,46,.06)}
.plock .dg{display:flex;gap:8px}
.plock .dg div{display:grid;justify-items:center;gap:2px}
.plock .dg button{width:44px;height:24px;border:1px solid var(--line2);background:#050a15;color:var(--muted)}
.plock .dg span{width:44px;height:52px;display:grid;place-items:center;font-family:var(--f-tech);font-size:28px;font-weight:700;background:#ece6d6;color:#17140f;border-radius:6px}
.safe.locked{opacity:.35;filter:grayscale(1);pointer-events:none}

.credits{animation:roll 26s linear forwards;display:grid;gap:22px}
.finale{min-height:88vh;display:grid;place-items:center;text-align:center}
.finale .inner{display:grid;gap:16px;justify-items:center;max-width:760px;width:100%}
.bigeye{width:120px;height:120px;border-radius:50%;border:3px solid var(--mint);display:grid;place-items:center;background:radial-gradient(circle,#06302a 0 52%,#030a12 54%);box-shadow:0 0 50px rgba(61,255,168,.45);animation:breathe 3.2s ease-in-out infinite}
.bigeye::after{content:"";width:34px;height:34px;border-radius:50%;background:radial-gradient(circle,#fff 0 18%,var(--mint) 22% 60%,#0b6b46 62%);box-shadow:0 0 24px var(--mint)}
@keyframes breathe{50%{box-shadow:0 0 90px rgba(61,255,168,.75);transform:scale(1.04)}}
.fline{font-size:clamp(18px,2.6vw,24px);line-height:1.6;min-height:1.6em}
.upd{font-family:var(--f-tech);letter-spacing:.2em;font-size:12px;color:var(--mint);border:1px solid var(--mint);padding:6px 12px}
.mem{display:grid;gap:8px;width:100%;text-align:left}
.mem p{margin:0;padding:8px 12px;border-left:3px solid var(--c);background:rgba(4,8,18,.6);font-size:15px;opacity:0;animation:fadein .8s forwards}
@keyframes fadein{to{opacity:1}}
.roster{display:grid;grid-template-columns:70px 1fr 1.4fr;gap:6px 10px;align-items:center}
.roster textarea{min-height:38px}

];
const NEWSQ = [
  ['지금 자율주행 버스 AI의 판단 기준은 누가 정하고 있나요?', ['버스 제조사','정부','시민 단체','버스 승객'], 0],
  ['시민 단체가 “위험하다”고 지적한 것은 무엇인가요?', ['버스가 너무 빠른 것','생명이 걸린 규칙을 기업 혼자 정하는 것','버스 요금이 비싼 것','운전석이 없는 것'], 1],
  ['전문가들이 “기술보다 중요하다”고 말한 것은?', ['더 빠른 AI 칩','판단 기준을 정하는 과정','버스 디자인','사고 보험료'], 1],
  ['토론회를 준비한 학생이 말한 기술 판단 기준의 주인은?', ['똑똑한 AI','버스 회사','사람이 함께','외국 전문가'], 2]

function pouchLock() {
  const d = St.plk || (St.plk = [0,0,0]);
  if (St.pouchOk) return `<div class="plock" style="border-color:var(--mint)"><div class="dlabel" style="color:var(--mint)">PARTS POUCH · UNLOCKED</div><div class="grant" style="font-size:22px">1 2 7</div><p class="small" style="margin:0;text-align:center">엔지니어는 <b>진짜 부품 파우치</b>를 이 번호로 열어 한 박사의 편지를 가져오세요.<br>그동안 나머지는 금고 다이얼을 푸세요.</p></div>`;
  return `<div class="plock"><div class="dlabel" style="color:var(--amber)">STEP 1 · 부품 파우치 자물쇠 (3자리)</div><div class="dg">${d.map((v,k) => `<div><button data-act="plk" data-k="${k}" data-d="1" aria-label="${k+1}번째 자리 올리기">▲</button><span>${v}</span><button data-act="plk" data-k="${k}" data-d="9" aria-label="${k+1}번째 자리 내리기">▼</button></div>`).join('')}</div><button class="btn small" style="--c:var(--amber)" data-act="plkCheck">자물쇠 당기기 ▸</button><span class="muted small">홀수 자리 합 + 짝수 자리 합 × 3</span><div id="plkmsg"></div></div>`;
}

if (T.step === 'news') { const a = St.newsA || (St.newsA = {}); const ok = NEWSQ.every((q,k) => a[k] === q[2]);
  return scene(3, commStatic('미래일보 판독 장치 가동. 2050년 시민이 아니면 크립텍스에 손댁 수 없습니다. 1면 기사를 읽고 시민 판독 질문 네 개에 답하십시오.'), `<h2><span class="no">MISSION 03-A</span>미래일보 판독 · 시민 인증</h2>
  <p>띠지를 뜯은 <b>미래일보 1면 기사</b>를 모둠원이 나눠 읽으세요. 답을 고르면 판독 램프가 켜집니다. 네 개 모두 맞아야 크립텍스 잠금이 풀려요.</p>
  <div class="newsq">${NEWSQ.map(([q,opts,ans],k) => `<div class="nq ${a[k]===ans?'ok':''}"><b><i class="lamp"></i>Q${k+1}. ${q}</b><div class="pills">${opts.map((o,n) => `<button class="pill" data-act="newsA" data-k="${k}" data-n="${n}" aria-pressed="${a[k]===n}">${o}</button>`).join('')}</div></div>`).join('')}</div>
  <div class="row"><button class="btn" data-act="newsCheck">시민 인증 ▸</button></div><div id="devmsg"></div>${hintBlock(3)}`); }

let finaleRun = 0;
function renderFinale() {
  FX.freeze(false); const T = St.T, id = ++finaleRun; if (St.finaleShown) return; St.finaleShown = true;
  $('#app').innerHTML = `<div class="finale"><div class="inner"><div class="bigeye" id="feye"></div><div class="upd" id="fupd">TEKI · REBOOTING</div><div class="fline" id="fl"></div><div class="mem" id="fmem"></div><div class="huge rgb" id="fend" style="font-size:clamp(28px,5vw,46px);opacity:0;transition:opacity 1.5s">기술의 중심에는, 언제나 사람이.</div></div></div>`;
  const lines = ['…여러분, 들리십니까. 테키입니다.', '처음 만났을 때 저는 쓸모없어 보이는 기술을 지우려고 했습니다.', '그런데 여러분과 다섯 시대를 여행하며 알게 되었습니다.', '모든 기술 뒤에는, 그것이 꼭 필요했던 누군가가 있었다는 것을.', '이제 저는 기술을 지우지 않겠습니다. 대신 매번 묻겠습니다.', '“이 기술은 누구를 위한 것인가요?”'];
  const fl = $('#fl'), mem = $('#fmem');
  (async () => { if (Sound.on) Sound.credits(30); await sleep(1500);
    for (const l of lines) { if (id !== finaleRun || !document.contains(fl)) return; fl.textContent = ''; for (let i=0;i<l.length;i++){ fl.textContent = l.slice(0,i+1); if (i%2===0) Sound.type(); await sleep(reduced?0:55); } await sleep(1500); }
    const up = $('#fupd'); if (up) { up.textContent = 'TEKI v2.0 · HUMAN-CENTERED ENGINEER MODE · ONLINE'; FX.flash('cy'); Sound.chip(); }
    fl.textContent = `${T.name}에게서 배운 것을 제 기억 칩에 영구 저장합니다.`;
    const items = [1,2,3,4,5].map(i => [i, i===3 ? (T.reasons[3] || '') : (T.reasons[i] || '')]).filter(x => x[1] && !/^\(/.test(x[1]));
    if (T.reflection) items.push([6, T.reflection]);
    for (const [i,t] of items) { if (!document.contains(mem)) return; mem.insertAdjacentHTML('beforeend', `<p style="--c:var(--c-${i})"><b style="color:var(--c-${i})">${i===6?'우리의 다짐':'CHIP '+'①②③④⑤'[i-1]}</b> ${esc(t)}</p>`); Sound.blip(); await sleep(1100); }
    await sleep(800); const e = $('#fend'); if (e) e.style.opacity = 1;
  })();
}
function renderEnding() { St.finaleShown = false;

case 'safe': { if (!St.pouchOk) { FX.deny($('.plock')); return; } St.safe += +b.dataset.d; Sound.tick(); const s = $('#safesvg'); if (s) s.style.transform = `rotate(${-St.safe*36}deg)`; $('#safeval').textContent = ((St.safe%10)+10)%10; return; }
case 'plk': { const k = +b.dataset.k; St.plk[k] = (St.plk[k] + (+b.dataset.d)) % 10; Sound.tick(); renderStudent(); return; }
case 'plkCheck': { if (St.plk.join('') === '127') { St.pouchOk = true; Sound.clack(); Sound.grant(); FX.flash('cy'); renderStudent(); } else { Sound.no(); FX.deny($('.plock')); const m = $('#plkmsg'); if (m) m.innerHTML = '<div class="deny" style="font-size:13px">LOCKED</div><p class="small muted" style="margin:0">자물쇠가 꿈쩍도 안 해요. 합계를 다시 계산해 보세요.</p>'; } return; }
case 'safeOpen': { if (!St.pouchOk) { FX.deny($('#safe')); $('#devmsg').innerHTML = '<div class="deny">LOCKED</div><p class="small muted">먼저 STEP 1 파우치 자물쇠 번호(합계)를 맞추세요.</p>'; return; } const v = ((St.safe%10)+10)%10; if (v === CODES.checksum) { Sound.grant(); $('#devmsg').innerHTML = '<div class="grant">VAULT OPEN</div>'; const s = $('#safesvg'); if (s) { s.style.transition = 'transform 1s'; s.style.transform = `rotate(${-St.safe*36 - 720}deg)`; } setTimeout(() => { setStep('reason'); grant(4); }, 1200); } else { $('#devmsg').innerHTML = '<div class="deny">VAULT LOCKED</div>'; FX.deny($('#safe')); } return; }

case 'newsA': { const A = St.newsA || (St.newsA = {}); A[+b.dataset.k] = +b.dataset.n; Sound.blip(); renderStudent(); return; }
case 'newsCheck': { const A = St.newsA || {}; const n = NEWSQ.filter((q,k) => A[k] === q[2]).length; Sound.scan();
  if (n === NEWSQ.length) { Sound.grant(); FX.flash('cy'); document.querySelectorAll('.nq').forEach(e => e.classList.add('ok')); $('#devmsg').innerHTML = '<div class="grant">CITIZEN VERIFIED</div><p class="small">판독 완료. 기사 속 사람들은 모두 같은 말을 하고 있습니다. 이제 진하게 찍힌 네 글자로 크립텍스를 여십시오.</p>'; setTimeout(() => setStep('keyword'), 1800); }
  else { FX.deny($('.newsq')); $('#devmsg').innerHTML = `<div class="deny">VERIFY FAILED</div><p class="small muted">맞은 답: ${n}/${NEWSQ.length} · 기사 본문에서 근거 문장을 찾아 보세요.</p>`; } return; }
